#!/usr/bin/env python3
"""Generate the angled placement meshes used by autogenerated node variants.

Run from this directory:  python3 gen_angled_models.py

Two shapes are produced, both derived from a unit cube with 45 degree corner
chamfers:

  angledwalls_diag.obj         two opposite corners chamfered -> diagonal wall
  angledwalls_diag_corner.obj  one corner chamfered -> joins a diagonal to an
                               axis-aligned wall

Both are authored in *node space* (X east, Y up, Z north, node spans +-0.5) and
emitted so that Luanti's OBJ loader reproduces them exactly:

  * irr/src/COBJMeshFileLoader.cpp negates X on load ("change handedness"), so
    positions and normals are written with X negated and every face loop is
    reversed to keep the winding outward-facing.
  * The loader ignores mtllib entirely and starts a new mesh buffer per `g`
    group, so groups are emitted in tile order: top, bottom, side.  A node def
    therefore uses  tiles = {top, bottom, side}.
  * UVs follow the engine's own nodebox convention (see makeCuboid() in
    src/client/content_mapblock.cpp) so partial faces line up with the textures
    of neighbouring full cubes.  Chamfer faces have no cube neighbour to match,
    so they are stretched to the full 0..1 range instead, which makes a run of
    diagonal blocks read as one continuous surface.
"""

import math

SHRINK = 0.9996  # hairline inset, stops z-fighting with neighbouring cubes

# Top outlines, counter-clockwise seen from above (right-hand rule -> +Y).
# diag:   |Z - X| <= 0.5     chamfers face SE and NW
# corner: Z >= X - 0.5       chamfer faces SE
OUTLINES = {
    "angledwalls_diag": [
        (0.5, 0.5), (0.5, 0.0), (0.0, -0.5), (-0.5, -0.5), (-0.5, 0.0), (0.0, 0.5),
    ],
    "angledwalls_diag_corner": [
        (0.5, 0.5), (0.5, 0.0), (0.0, -0.5), (-0.5, -0.5), (-0.5, 0.5),
    ],
}


def norm(v):
    length = math.sqrt(sum(c * c for c in v))
    return tuple(c / length for c in v)


def build(outline):
    """Return [(group, normal, [(pos, uv), ...]), ...] in node space."""
    faces = []

    # Top and bottom: 1:1 planar projection, matching a full cube's up/down face.
    top = [((x, 0.5, z), (0.5 + x, 0.5 + z)) for x, z in outline]
    faces.append(("top", (0.0, 1.0, 0.0), top))
    bottom = [((x, -0.5, z), (0.5 + x, 0.5 - z)) for x, z in reversed(outline)]
    faces.append(("bottom", (0.0, -1.0, 0.0), bottom))

    for i, (ax, az) in enumerate(outline):
        bx, bz = outline[(i + 1) % len(outline)]
        n = norm((-(bz - az), 0.0, bx - ax))          # outward, edge rotated -90 deg
        d = (-n[2], 0.0, n[0])                        # u axis, engine convention
        chamfer = abs(n[0]) > 1e-6 and abs(n[2]) > 1e-6
        k = math.sqrt(2.0) if chamfer else 1.0        # stretch chamfers to 0..1

        def uv(x, y, z):
            return (0.5 + (x * d[0] + z * d[2]) * k, 0.5 + y)

        quad = [
            ((ax, -0.5, az), uv(ax, -0.5, az)),
            ((bx, -0.5, bz), uv(bx, -0.5, bz)),
            ((bx, 0.5, bz), uv(bx, 0.5, bz)),
            ((ax, 0.5, az), uv(ax, 0.5, az)),
        ]
        faces.append(("side", n, quad))

    return faces


def emit(name, faces):
    verts, uvs, normals = [], [], []
    index = {}

    def intern(store, value):
        key = (id(store), value)
        if key not in index:
            store.append(value)
            index[key] = len(store)
        return index[key]

    # Group faces by material, preserving tile order: top, bottom, side.
    lines = [
        "# %s.obj -- generated by models/.dev/gen_angled_models.py, do not edit" % name,
        "# mesh buffers in tile order: tiles = {top, bottom, side}",
    ]
    for group in ("top", "bottom", "side"):
        member = [f for f in faces if f[0] == group]
        if not member:
            continue
        body = []
        for _, n, loop in member:
            ni = intern(normals, (-n[0], n[1], n[2]))
            corners = []
            for pos, uv in reversed(loop):  # reversed: loader negates X
                vi = intern(verts, (-pos[0] * SHRINK, pos[1] * SHRINK, pos[2] * SHRINK))
                ti = intern(uvs, uv)
                corners.append("%d/%d/%d" % (vi, ti, ni))
            body.append("f " + " ".join(corners))
        lines.append("g " + group)
        lines.append("usemtl angledwalls_" + group)
        lines.extend(body)

    header = ["v %.6f %.6f %.6f" % v for v in verts]
    header += ["vt %.6f %.6f" % t for t in uvs]
    header += ["vn %.4f %.4f %.4f" % n for n in normals]

    with open("../%s.obj" % name, "w") as fh:
        fh.write("\n".join(lines[:2] + header + lines[2:]) + "\n")
    print("%s.obj: %d verts, %d faces" % (name, len(verts), len(faces)))


for name, outline in OUTLINES.items():
    emit(name, build(outline))
